// Cloudflare Worker entry: the OpenNext app, plus a cron trigger (every 15 min,
// see wrangler.jsonc) that runs /api/cron/messages: queue and send due texts,
// retry failed refunds. The request goes straight into the app (no network
// hop); the route still checks the Bearer CRON_SECRET.
// The module only exists after `opennextjs-cloudflare build`, so the error comes and goes.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; NEXT_PUBLIC_SITE_URL?: string };

const worker = {
  fetch: handler.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) return;
    const site = env.NEXT_PUBLIC_SITE_URL ?? "https://beadup.app";
    const req = new Request(`${site}/api/cron/messages`, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

export default worker;
